     1	// The shared MHPCO vocabulary: the customer and the items a policy can cover,
     2	// mirroring the binding input schema. Both operations read this vocabulary --
     3	// quote reads cursed and enchantment for its risk surcharges, claim reads
     4	// material and enchantment for its reimbursement clauses -- so it belongs to
     5	// neither operation's policy module.
     6	export interface Customer {
     7	  yearsWithMHPCO: number;
     8	}
     9	
    10	export interface Item {
    11	  type: string;
    12	  cursed?: boolean;
    13	  enchantment?: number;
    14	  material?: string;
    15	}
===== src/price-list.ts =====
     1	import type { Item } from "./insured-item.js";
     2	
     3	// The MHPCO price list. Each listed item type carries a pair: what the MHPCO
     4	// insures it for and what it charges to insure it. The spec states the two
     5	// columns as one row per type, and both operations read this same list --
     6	// quote reads the base premium column, claim the insurance value column -- so
     7	// the list belongs to neither operation and changes for one reason only: the
     8	// MHPCO revises its prices or its catalogue of item types.
     9	interface ListedPrice {
    10	  insuranceValue: number;
    11	  basePremium: number;
    12	}
    13	
    14	const MAIN_ITEM_PRICES: Record<string, ListedPrice> = {
    15	  sword: { insuranceValue: 1000, basePremium: 100 },
    16	  amulet: { insuranceValue: 600, basePremium: 60 },
    17	  staff: { insuranceValue: 800, basePremium: 80 },
    18	  potion: { insuranceValue: 400, basePremium: 40 },
    19	};
    20	
    21	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
    22	const COMPONENT_PRICE: ListedPrice = { insuranceValue: 250, basePremium: 25 };
    23	
    24	// Components are listed as one undifferentiated kind rather than by type: the
    25	// price list names no individual component, only the kind and its single price.
    26	export function isComponent(item: Item): boolean {
    27	  return COMPONENT_TYPES.has(item.type);
    28	}
    29	
    30	// The MHPCO insures only what its price list names; anything else is refused.
    31	function listedPrice(item: Item): ListedPrice {
    32	  if (isComponent(item)) {
    33	    return COMPONENT_PRICE;
    34	  }
    35	  const price = MAIN_ITEM_PRICES[item.type];
    36	  if (price === undefined) {
    37	    throw new Error(`the MHPCO price list does not cover "${item.type}"`);
    38	  }
    39	  return price;
    40	}
    41	
    42	export function insuranceValue(item: Item): number {
    43	  return listedPrice(item).insuranceValue;
    44	}
    45	
    46	// An item's own price per the MHPCO price list. A component is listed at its
    47	// individual price here; the block discount is a property of a group of alike
    48	// components, not of any single component.
    49	export function itemBasePremium(item: Item): number {
    50	  return listedPrice(item).basePremium;
    51	}
    52	
    53	export const COMPONENT_BASE_PREMIUM = COMPONENT_PRICE.basePremium;
===== src/mhpcos-favor.ts =====
     1	// "All amounts are rounded to whole G in the MHPCO's favor" is one MHPCO
     2	// policy with two directions, because the MHPCO stands on opposite sides of
     3	// the two amounts: a premium is money owed to it, so a fraction is rounded up;
     4	// a payout is money owed by it, so a fraction is rounded down. Both directions
     5	// live here so the policy -- and the asymmetry that defines it -- has one home.
     6	export function amountOwedToMhpco(amount: number): number {
     7	  return Math.ceil(amount);
     8	}
     9	
    10	export function amountOwedByMhpco(amount: number): number {
    11	  return Math.floor(amount);
    12	}
===== src/quote.ts =====
     1	import type { Customer, Item } from "./insured-item.js";
     2	import { amountOwedToMhpco } from "./mhpcos-favor.js";
     3	import {
     4	  COMPONENT_BASE_PREMIUM,
     5	  isComponent,
     6	  itemBasePremium,
     7	} from "./price-list.js";
     8	
     9	const PROCESSING_FEE = 5;
    10	const CURSE_SURCHARGE_RATE = 0.5;
    11	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    12	const HIGH_ENCHANTMENT_LEVEL = 5;
    13	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    14	const LOYALTY_DISCOUNT_RATE = 0.2;
    15	const LOYALTY_YEARS = 2;
    16	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    17	
    18	const BLOCK_SIZE = 3;
    19	const BLOCK_BASE_PREMIUM = 60;
    20	
    21	function alikeComponentGroupSizes(components: Item[]): number[] {
    22	  const sizePerType = new Map<string, number>();
    23	  for (const component of components) {
    24	    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
    25	  }
    26	  return [...sizePerType.values()];
    27	}
    28	
    29	function alikeComponentGroupBasePremium(groupSize: number): number {
    30	  return groupSize === BLOCK_SIZE
    31	    ? BLOCK_BASE_PREMIUM
    32	    : groupSize * COMPONENT_BASE_PREMIUM;
    33	}
    34	
    35	function componentsBasePremium(components: Item[]): number {
    36	  return alikeComponentGroupSizes(components)
    37	    .map(alikeComponentGroupBasePremium)
    38	    .reduce((sum, premium) => sum + premium, 0);
    39	}
    40	
    41	function mainItemsBasePremium(mainItems: Item[]): number {
    42	  return mainItems
    43	    .map(itemBasePremium)
    44	    .reduce((sum, premium) => sum + premium, 0);
    45	}
    46	
    47	function policyBasePremium(items: Item[]): number {
    48	  return (
    49	    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
    50	    componentsBasePremium(items.filter(isComponent))
    51	  );
    52	}
    53	
    54	interface ItemRisk {
    55	  applies: (item: Item) => boolean;
    56	  surchargeRate: number;
    57	}
    58	
    59	const isCursed = (item: Item): boolean => item.cursed === true;
    60	
    61	const isHighlyEnchanted = (item: Item): boolean =>
    62	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
    63	
    64	const ITEM_RISKS: ItemRisk[] = [
    65	  { applies: isCursed, surchargeRate: CURSE_SURCHARGE_RATE },
    66	  { applies: isHighlyEnchanted, surchargeRate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
    67	];
    68	
    69	function itemRiskSurcharge(item: Item): number {
    70	  return ITEM_RISKS.filter((risk) => risk.applies(item))
    71	    .map((risk) => itemBasePremium(item) * risk.surchargeRate)
    72	    .reduce((sum, surcharge) => sum + surcharge, 0);
    73	}
    74	
    75	function itemRiskSurcharges(items: Item[]): number {
    76	  return items
    77	    .map(itemRiskSurcharge)
    78	    .reduce((sum, surcharge) => sum + surcharge, 0);
    79	}
    80	
    81	// Every item in a quote is insured for the first time, so the initial assessment
    82	// surcharge applies to every quote -- it does not depend on the customer's history.
    83	function initialAssessmentOnEveryQuote(basePremium: number): number {
    84	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
    85	}
    86	
    87	interface CustomerStanding {
    88	  yearsWithMHPCO: number;
    89	  previousContracts: number;
    90	}
    91	
    92	interface CustomerStandingDiscount {
    93	  earnedBy: (standing: CustomerStanding) => boolean;
    94	  discountRate: number;
    95	}
    96	
    97	const isLongStanding = (standing: CustomerStanding): boolean =>
    98	  standing.yearsWithMHPCO >= LOYALTY_YEARS;
    99	
   100	const isFollowUpContract = (standing: CustomerStanding): boolean =>
   101	  standing.previousContracts > 0;
   102	
   103	const CUSTOMER_STANDING_DISCOUNTS: CustomerStandingDiscount[] = [
   104	  { earnedBy: isLongStanding, discountRate: LOYALTY_DISCOUNT_RATE },
   105	  { earnedBy: isFollowUpContract, discountRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
   106	];
   107	
   108	function customerStandingDiscounts(
   109	  standing: CustomerStanding,
   110	  basePremium: number,
   111	): number {
   112	  return CUSTOMER_STANDING_DISCOUNTS.filter((discount) =>
   113	    discount.earnedBy(standing),
   114	  )
   115	    .map((discount) => basePremium * discount.discountRate)
   116	    .reduce((sum, amount) => sum + amount, 0);
   117	}
   118	
   119	function policyWideModifiers(
   120	  standing: CustomerStanding,
   121	  basePremium: number,
   122	): number {
   123	  return (
   124	    initialAssessmentOnEveryQuote(basePremium) -
   125	    customerStandingDiscounts(standing, basePremium)
   126	  );
   127	}
   128	
   129	export function quote(
   130	  customer: Customer,
   131	  items: Item[],
   132	  previousContracts: number,
   133	): number {
   134	  const basePremium = policyBasePremium(items);
   135	  const standing = { ...customer, previousContracts };
   136	  const premium =
   137	    basePremium +
   138	    itemRiskSurcharges(items) +
   139	    policyWideModifiers(standing, basePremium) +
   140	    PROCESSING_FEE;
   141	  // A premium is owed to the MHPCO, so its fraction is rounded up.
   142	  return amountOwedToMhpco(premium);
   143	}
===== src/claim.ts =====
     1	import type { Item } from "./insured-item.js";
     2	import { amountOwedByMhpco } from "./mhpcos-favor.js";
     3	import { insuranceValue } from "./price-list.js";
     4	
     5	export interface Damage {
     6	  itemType: string;
     7	  amount: number;
     8	}
     9	
    10	export interface Incident {
    11	  cause: string;
    12	  damages: Damage[];
    13	}
    14	
    15	export interface Policy {
    16	  insuredItems: Item[];
    17	  // How much the MHPCO may still pay out over this policy's lifetime. This is
    18	  // the single figure the MHPCO tracks per policy: opening the policy sets it
    19	  // to the full cap, and each claim depletes it. The insurance sum it is
    20	  // derived from is never reported on its own.
    21	  remainingCap: number;
    22	}
    23	
    24	export interface ClaimResult {
    25	  payout: number;
    26	  remainingCap: number;
    27	  // The policy as it stands after this claim, for settling the next one.
    28	  policy: Policy;
    29	}
    30	
    31	const DEDUCTIBLE_PER_DAMAGE = 100;
    32	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    33	
    34	// The MHPCO insures a policy for the sum of its items' insurance values.
    35	function insuranceSum(insuredItems: Item[]): number {
    36	  return insuredItems
    37	    .map(insuranceValue)
    38	    .reduce((sum, value) => sum + value, 0);
    39	}
    40	
    41	// The MHPCO pays out at most twice the insurance sum over a policy's lifetime.
    42	// A policy is opened with that whole cap intact; each claim depletes it.
    43	export function openPolicy(insuredItems: Item[]): Policy {
    44	  return {
    45	    insuredItems,
    46	    remainingCap: insuranceSum(insuredItems) * CAP_MULTIPLE_OF_INSURANCE_SUM,
    47	  };
    48	}
    49	
    50	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    51	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    52	const FULL_REIMBURSEMENT_RATE = 1;
    53	
    54	// A damage entry names only the type of the item it befell, so the MHPCO
    55	// identifies the covering item no further than the policy's first insured item
    56	// of that type. Where a policy covers several alike items this is a deliberate
    57	// approximation: alike items share the traits the reimbursement clauses read,
    58	// so any of them yields the same clause.
    59	function firstInsuredItemCoveringDamage(
    60	  policy: Policy,
    61	  damage: Damage,
    62	): Item | undefined {
    63	  return policy.insuredItems.find((item) => item.type === damage.itemType);
    64	}
    65	
    66	// The conditions on which the MHPCO accepts a single damage entry, each
    67	// readable from that entry alone: it settles a damage only against an item the
    68	// policy actually covers, and a damage event reports what was lost, so its
    69	// amount cannot be negative. An entry that fails either condition is refused,
    70	// and the whole claim with it. Accepting an entry yields the covering item,
    71	// since establishing coverage is what finds it.
    72	function acceptedDamageEntryCover(policy: Policy, damage: Damage): Item {
    73	  const covering = firstInsuredItemCoveringDamage(policy, damage);
    74	  if (covering === undefined) {
    75	    throw new Error(`the policy does not cover "${damage.itemType}"`);
    76	  }
    77	  if (damage.amount < 0) {
    78	    throw new Error(
    79	      `a damage amount cannot be negative, but "${damage.itemType}" reports ${damage.amount}`,
    80	    );
    81	  }
    82	  return covering;
    83	}
    84	
    85	function isHighlyEnchanted(item: Item): boolean {
    86	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    87	}
    88	
    89	// Which reimbursement clause covers the damaged item. Damage to a highly
    90	// enchanted item is reimbursed at half; all other damage in full.
    91	// The dragon-material clause is subsumed by that default: it reimburses in
    92	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    93	// it never changes a payout and needs no branch of its own.
    94	// Every item reaching a clause is one the policy covers: whether the MHPCO
    95	// accepts the damage entry at all is settled beforehand, not here.
    96	function reimbursementRateFor(item: Item): number {
    97	  return isHighlyEnchanted(item)
    98	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    99	    : FULL_REIMBURSEMENT_RATE;
   100	}
   101	
   102	// The MHPCO settles each accepted damage event separately: it reimburses the
   103	// damage under the applicable clause, then withholds its deductible once per
   104	// event.
   105	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
   106	  const rate = reimbursementRateFor(acceptedDamageEntryCover(policy, damage));
   107	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
   108	}
   109	
   110	function countByType(types: string[]): Map<string, number> {
   111	  const counts = new Map<string, number>();
   112	  for (const type of types) {
   113	    counts.set(type, (counts.get(type) ?? 0) + 1);
   114	  }
   115	  return counts;
   116	}
   117	
   118	// The condition on which the MHPCO accepts a whole incident, checked before it
   119	// settles any of its damage entries. An incident can damage an insured item
   120	// only once, so an incident reporting more damages of a type than the policy
   121	// covers of it is refused, and every entry in it with it. This is the
   122	// incident-level counterpart to the per-entry conditions in
   123	// acceptedDamageEntryCover: it reads the damages as a whole, which no single
   124	// entry can.
   125	function acceptIncidentAgainstInsuredItems(
   126	  policy: Policy,
   127	  incident: Incident,
   128	): void {
   129	  const insured = countByType(policy.insuredItems.map((item) => item.type));
   130	  for (const [type, damaged] of countByType(
   131	    incident.damages.map((damage) => damage.itemType),
   132	  )) {
   133	    if (damaged > (insured.get(type) ?? 0)) {
   134	      throw new Error(
   135	        `the policy covers ${insured.get(type) ?? 0} of "${type}", but the incident reports ${damaged} damaged`,
   136	      );
   137	    }
   138	  }
   139	}
   140	
   141	// What the MHPCO owes for the whole incident before rounding: every damage
   142	// event settled under its clause, reduced to what the policy's lifetime cap
   143	// still allows.
   144	function cappedSettlement(policy: Policy, incident: Incident): number {
   145	  const settled = incident.damages
   146	    .map((damage) => settlementForDamageEvent(policy, damage))
   147	    .reduce((sum, amount) => sum + amount, 0);
   148	  return Math.min(settled, policy.remainingCap);
   149	}
   150	
   151	export function claim(policy: Policy, incident: Incident): ClaimResult {
   152	  acceptIncidentAgainstInsuredItems(policy, incident);
   153	  // A payout is owed by the MHPCO, so its fraction is rounded down. Only this
   154	  // final amount is rounded; the settlement above stays fractional. Rounding
   155	  // last is safe for a capped claim too: the cap is always a whole number of
   156	  // G, so rounding a capped settlement changes nothing.
   157	  const payout = amountOwedByMhpco(cappedSettlement(policy, incident));
   158	  const remainingCap = policy.remainingCap - payout;
   159	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
   160	}
===== src/scenario.ts =====
     1	import { claim, openPolicy } from "./claim.js";
     2	import type { Incident, Policy } from "./claim.js";
     3	import type { Customer, Item } from "./insured-item.js";
     4	import { quote } from "./quote.js";
     5	
     6	export interface QuoteStep {
     7	  op: "quote";
     8	  items: Item[];
     9	}
    10	
    11	export interface ClaimStep {
    12	  op: "claim";
    13	  policy: number;
    14	  incident: Incident;
    15	}
    16	
    17	export type Step = QuoteStep | ClaimStep;
    18	
    19	export interface Scenario {
    20	  customer: Customer;
    21	  steps: Step[];
    22	}
    23	
    24	export interface QuoteResult {
    25	  premium: number;
    26	}
    27	
    28	export interface ClaimStepResult {
    29	  payout: number;
    30	  remainingCap: number;
    31	}
    32	
    33	export type StepResult = QuoteResult | ClaimStepResult;
    34	
    35	// The MHPCO settles a scenario's steps in order for a single customer: each
    36	// quote opens a policy the later claims draw on, and every quote after the
    37	// customer's first is a follow-up contract.
    38	export function runScenario(scenario: Scenario): StepResult[] {
    39	  const policies = new Map<number, Policy>();
    40	  let previousContracts = 0;
    41	  return scenario.steps.map((step, stepIndex) => {
    42	    if (step.op === "quote") {
    43	      const premium = quote(scenario.customer, step.items, previousContracts);
    44	      previousContracts += 1;
    45	      policies.set(stepIndex, openPolicy(step.items));
    46	      return { premium };
    47	    }
    48	    const result = claim(policyFor(policies, step.policy), step.incident);
    49	    policies.set(step.policy, result.policy);
    50	    return { payout: result.payout, remainingCap: result.remainingCap };
    51	  });
    52	}
    53	
    54	function policyFor(policies: Map<number, Policy>, stepIndex: number): Policy {
    55	  const policy = policies.get(stepIndex);
    56	  if (policy === undefined) {
    57	    throw new Error(`step ${stepIndex} did not create a policy`);
    58	  }
    59	  return policy;
    60	}
